package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.TenantsVO;

@RequiredArgsConstructor
public class TenantsValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<TenantsVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<Integer> getTenants() {
    return value.map(TenantsVO::getTenants);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<TenantsVO> getTenantsValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public TenantsVO readTenants(final Optional<ObservedIssue> original,
      final ConstraintFailList fails) {
    TenantsVO result = value.orElse(original.map(ObservedIssue::getTenantsValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "tenants", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param tenants
   * @return
   */
  public T tenants(TenantsVO tenants) {
    this.value = Optional.of(tenants);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param tenants
   * @return
   */
  public T tenants(Optional<TenantsVO> tenants) {
    this.value = tenants;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param tenants
   * @return
   */
  public T tenants(Integer tenants) {
    this.value = Optional.of(TenantsVO.from(tenants));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetTenants() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetTenantsIfMatches(final String field) {
    if ("tenants".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
